<?php require_once 'bootstrap.php';$u=require_login();$id=(string)($_GET['id']??'');$st=db()->prepare('SELECT * FROM academy_courses WHERE sic_id=?');$st->execute([$id]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Corso non trovato');}db()->prepare('INSERT OR IGNORE INTO academy_enrollments(sic_id,user_sic_id,course_sic_id) VALUES(?,?,?)')->execute([sic_id(),$u['sic_id'],$id]);$en=db()->prepare('SELECT * FROM academy_enrollments WHERE user_sic_id=? AND course_sic_id=?');$en->execute([$u['sic_id'],$id]);$er=$en->fetch();$ls=db()->prepare('SELECT al.*,CASE WHEN alp.status="COMPLETED" THEN 1 ELSE 0 END completed FROM academy_lessons al LEFT JOIN academy_lesson_progress alp ON alp.lesson_sic_id=al.sic_id AND alp.enrollment_sic_id=? WHERE al.course_sic_id=? ORDER BY al.lesson_order');$ls->execute([$er['sic_id'],$id]);$lessons=$ls->fetchAll();$pageTitle=$c['title'];require '_header.php';?><section class="section-head"><div><span class="eyebrow"><?=h($c['category'])?></span><h1><?=h($c['title'])?></h1><p><?=h($c['description'])?></p></div></section><?php foreach($lessons as $l):?><section class="card"><span class="pill"><?=h((string)$l['lesson_order'])?> · <?=h($l['lesson_type'])?></span><h2><?=h($l['title'])?></h2><?=$l['content_html']?><p>Durata indicativa: <?=h((string)$l['duration_min'])?> min · +<?=h((string)$l['drx_reward'])?> DRX</p><?php if($l['completed']):?><div class="success">✓ Completata</div><?php else:?><form method="post" action="action.php"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="academy_lesson_complete"><input type="hidden" name="lesson_sic_id" value="<?=h($l['sic_id'])?>"><input type="hidden" name="return" value="academy-course.php?id=<?=urlencode($id)?>"><button class="btn primary">Segna completata</button></form><?php endif;?></section><?php endforeach;?><?php require '_footer.php';?>